SELECT     TRUNC(SYSDATE)                                        AS REPORT_DATE,     im.DEPT                                               AS DEPT_NO,     d.DEPT_NAME                                           AS DEPT_NAME,     im.ITEM                                               AS ITEM_ID,     im.ITEM_DESC                                          AS ITEM_DESCRIPTION,     im.STANDARD_UOM                                       AS UOM,     ils.LOC                                               AS LOCATION_ID,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END  AS LOCATION_NAME,        isc.SUPPLIER                                          AS SUPPLIER_ID,     isc.UNIT_COST                                         AS SUPPLIER_NET_COST,        ils.AV_COST                                           AS WEIGHTED_AVG_COST,        ROUND(NVL(ils.AV_COST,0) - NVL(isc.UNIT_COST,0),4)  AS WAC_VS_NET_COST_VARIANCE,     ROUND((NVL(ils.AV_COST,0) - NVL(isc.UNIT_COST,0))           / NULLIF(isc.UNIT_COST,0) * 100,2)             AS VARIANCE_PCT,     ils.STOCK_ON_HAND                                     AS STOCK_ON_HAND,     ROUND(ils.STOCK_ON_HAND * ils.AV_COST,2)             AS SOH_AT_WAC,     ROUND(ils.STOCK_ON_HAND * NVL(isc.UNIT_COST,0),2)   AS SOH_AT_NET_COST,     il.SELLING_UNIT_RETAIL                                        AS UNIT_RETAIL  FROM  MFCS_RDS.RDS_WV_ITEM_LOC_SOH            ils JOIN  MFCS_RDS.RDS_WV_ITEM_LOC                il   ON ils.ITEM = il.ITEM AND ils.LOC = il.LOC JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER             im   ON ils.ITEM = im.ITEM AND im.TRAN_LEVEL = im.ITEM_LEVEL JOIN  MFCS_RDS.RDS_WV_DEPS                    d    ON im.DEPT  = d.DEPT LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY   isc  ON im.ITEM  = isc.ITEM AND isc.PRIMARY_SUPP_IND='Y' AND isc.PRIMARY_COUNTRY_IND='Y' LEFT JOIN MFCS_RDS.RDS_WV_STORE               st   ON ils.LOC  = st.STORE AND il.LOC_TYPE = 'S' LEFT JOIN MFCS_RDS.RDS_WV_WH                  wh   ON ils.LOC  = wh.WH   AN